const fs=require('fs'),zlib=require('zlib');
function decode(file){
  const buf=fs.readFileSync(file);
  let pos=8, w,h,bd,ct, idat=[];
  while(pos<buf.length){
    const len=buf.readUInt32BE(pos); const type=buf.toString('ascii',pos+4,pos+8);
    const data=buf.slice(pos+8,pos+8+len);
    if(type==='IHDR'){w=data.readUInt32BE(0);h=data.readUInt32BE(4);bd=data[8];ct=data[9];}
    if(type==='IDAT')idat.push(data);
    pos+=12+len;
  }
  const raw=zlib.inflateSync(Buffer.concat(idat));
  const ch=ct===6?4:ct===2?3:ct===0?1:4;
  const stride=w*ch;
  const out=Buffer.alloc(h*stride);
  let p=0;
  for(let y=0;y<h;y++){
    const f=raw[p++]; const line=raw.slice(p,p+stride); p+=stride;
    for(let x=0;x<stride;x++){
      const a=x>=ch?out[y*stride+x-ch]:0;
      const b=y>0?out[(y-1)*stride+x]:0;
      const c=(x>=ch&&y>0)?out[(y-1)*stride+x-ch]:0;
      let v=line[x];
      if(f===1)v+=a; else if(f===2)v+=b; else if(f===3)v+=Math.floor((a+b)/2);
      else if(f===4){const pp=a+b-c,pa=Math.abs(pp-a),pb=Math.abs(pp-b),pc=Math.abs(pp-c);v+= (pa<=pb&&pa<=pc)?a:(pb<=pc?b:c);}
      out[y*stride+x]=v&255;
    }
  }
  return {w,h,ch,data:out};
}
const im=decode(process.argv[2]);
console.log('size',im.w,im.h,'ch',im.ch);
const x0=+process.argv[3],y0=+process.argv[4],x1=+process.argv[5],y1=+process.argv[6];
const counts={};
for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){
  const i=(y*im.w+x)*im.ch; const r=im.data[i],g=im.data[i+1],b=im.data[i+2];
  const k=r+','+g+','+b; counts[k]=(counts[k]||0)+1;
}
const top=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,8);
console.log(top.map(t=>t[0]+' x'+t[1]).join('\n'));
EOF
